[tool_use Bash: {"command": "python -B - <<'EOF'
import ast, pathlib
for path in sorted(pathlib.Path("ledgerkit").rglob("*.py")):
    tree = ast.parse(path.read_text())
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith("_"):
            args = node.args.posonlyargs + node.args.args + node.args.kwonlyargs + [a for a in (node.args.vararg, node.args.kwarg) if a]
            missing = [a.arg for a in args if a.annotation is None and a.arg not in ("self", "cls")]
            if missing or node.returns is None:
                print(f"{path}:{node.lineno} {node.name} missing={missing} return={'ok' if node.returns else 'MISSING'}")
print("annotation scan done")
EOF", "description": "Find public functions lacking full annotations"}]
